#!/bin/sh
# Container entrypoint (runs under tini). Prepares state and secrets, then
# hands over to supervisord, which runs and restarts every service.
set -eu
LOG_NAME=init
. /opt/scrcpy-web/bin/common.sh

umask 077
mkdir -p "$RUN_DIR" "$DATA_DIR/adb"
chmod 700 "$RUN_DIR"

# --- ADB keys -------------------------------------------------------------
# Keys are generated by adb on first start and kept in the data volume, so
# every installation has its own key and "Always allow" survives upgrades.
if [ ! -L /root/.android ]; then
  rm -rf /root/.android
  ln -s "$DATA_DIR/adb" /root/.android
fi

# --- Stale X server state from a previous run of this container ----------
rm -f /tmp/.X1-lock /tmp/.X11-unix/X1

# --- Session signing secret ----------------------------------------------
if [ ! -s "$DATA_DIR/session-secret" ]; then
  random_token 48 > "$DATA_DIR/session-secret"
fi

# --- Web UI password ------------------------------------------------------
WEB_AUTH="$(printf '%s' "${WEB_AUTH:-password}" | tr '[:upper:]' '[:lower:]')"
rm -f "$RUN_DIR/web-password"
case "$WEB_AUTH" in
  none)
    log "WARNING: WEB_AUTH=none - the web UI and API have NO authentication."
    log "         Only use this behind your own authenticating reverse proxy."
    ;;
  password)
    pw="$(read_secret WEB_PASSWORD)"
    if [ -z "$pw" ]; then
      if [ ! -s "$DATA_DIR/web-password" ]; then
        random_token 20 > "$DATA_DIR/web-password"
        log "No WEB_PASSWORD set, generated one: $(cat "$DATA_DIR/web-password")"
        log "It is stored in $DATA_DIR/web-password (set WEB_PASSWORD to choose your own)."
      else
        log "Using the generated web password stored in $DATA_DIR/web-password"
      fi
      pw="$(cat "$DATA_DIR/web-password")"
    fi
    printf '%s' "$pw" > "$RUN_DIR/web-password"
    ;;
  *)
    log "ERROR: WEB_AUTH must be 'password' or 'none' (got '$WEB_AUTH')"
    exit 1
    ;;
esac
export WEB_AUTH

# --- Optional API token and unlock PIN ------------------------------------
rm -f "$RUN_DIR/api-token" "$RUN_DIR/unlock-pin"
tok="$(read_secret API_TOKEN)"
[ -n "$tok" ] && printf '%s' "$tok" > "$RUN_DIR/api-token"
pin="$(read_secret UNLOCK_PIN)"
[ -n "$pin" ] && printf '%s' "$pin" > "$RUN_DIR/unlock-pin"
unset pw tok pin

# --- Native VNC access ----------------------------------------------------
# Off by default: the web UI talks to the VNC server over a private unix
# socket. Setting VNC_PASSWORD (or VNC_ENABLE=true) also opens a TCP port for
# VNC apps.
vnc_pw="$(read_secret VNC_PASSWORD)"
if [ -z "${VNC_ENABLE:-}" ]; then
  if [ -n "$vnc_pw" ]; then VNC_ENABLE=true; else VNC_ENABLE=false; fi
fi
rm -f "$RUN_DIR/vnc.passwd" "$RUN_DIR/vnc-password"
if is_true "$VNC_ENABLE"; then
  if [ -z "$vnc_pw" ]; then
    if [ ! -s "$DATA_DIR/vnc-password" ]; then
      random_token 8 > "$DATA_DIR/vnc-password"
      log "VNC_ENABLE=true but no VNC_PASSWORD set, generated one: $(cat "$DATA_DIR/vnc-password")"
    fi
    vnc_pw="$(cat "$DATA_DIR/vnc-password")"
  fi
  if [ "${#vnc_pw}" -gt 8 ]; then
    log "WARNING: VNC passwords are limited to 8 characters by the VNC protocol;"
    log "         only the first 8 characters of VNC_PASSWORD are used."
    vnc_pw="$(printf '%s' "$vnc_pw" | cut -c1-8)"
  fi
  printf '%s\n' "$vnc_pw" | vncpasswd -f > "$RUN_DIR/vnc.passwd"
  printf '%s' "$vnc_pw" > "$RUN_DIR/vnc-password"
  log "Native VNC enabled on port ${VNC_PORT:-5900} (unencrypted - keep it on a private network/VPN)."
fi
unset vnc_pw
export VNC_ENABLE

# --- Summary ----------------------------------------------------------------
log "scrcpy-web ${SCRCPY_WEB_VERSION:-dev} ($(scrcpy --version 2>/dev/null | head -n1))"
log "Web UI on port ${WEB_PORT:-8080} ($( [ -n "${TLS_CERT:-}" ] && echo https || echo http ))"
if is_true "${ADB_EXPOSE:-false}"; then
  log "ADB server exposed on port $ADB_PORT (no authentication - keep it on a private network/VPN)."
fi
[ -n "${ADB_SERIAL:-}" ] && log "Using device $ADB_SERIAL"

exec /usr/bin/supervisord -n -c /etc/supervisor/scrcpy-web.conf
